package com.projexa.coaching.users.entity;
import jakarta.persistence.*; import java.util.*;
@Entity @Table(name="users") public class User { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @Column(nullable=false) private UUID tenantId; @Column(unique=false) private String email; private String phone; @Column(nullable=false) private String passwordHash; @Column(nullable=false) private String firstName; private String lastName; @Column(nullable=false) private String status="ACTIVE"; @ManyToMany(fetch=FetchType.EAGER) @JoinTable(name="user_roles",joinColumns=@JoinColumn(name="user_id"),inverseJoinColumns=@JoinColumn(name="role_id")) private Set<Role> roles=new HashSet<>(); public UUID getId(){return id;} public UUID getTenantId(){return tenantId;} public String getEmail(){return email;} public String getPasswordHash(){return passwordHash;} public String getFirstName(){return firstName;} public String getLastName(){return lastName;} public String getStatus(){return status;} public Set<Role> getRoles(){return roles;} }
